import React, { useRef, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Link, useLocation } from 'react-router-dom';
import './App.css';
import Header from './components/Header/Header';
import Footer from './components/Footer/Footer';
import Home from './pages/Home/Home';
import About from './pages/About/About';
import Projects from './pages/Projects/Projects';
import Contact from './pages/Contact/Contact';

function App() {
  const homeRef = useRef<HTMLDivElement>(null);
  const aboutRef = useRef<HTMLDivElement>(null);
  const projectsRef = useRef<HTMLDivElement>(null);
  const contactRef = useRef<HTMLDivElement>(null);
  const location = useLocation();

  useEffect(() => {
    // Scroll to top of the page on route change
    window.scrollTo(0, 0);
  }, [location]);

  // Smooth scroll function
  const scrollToSection = (section: string) => {
    let targetRef: React.MutableRefObject<HTMLDivElement | null> | null = null;

    switch (section) {
      case 'home':
        targetRef = homeRef;
        break;
      case 'about':
        targetRef = aboutRef;
        break;
      case 'projects':
        targetRef = projectsRef;
        break;
      case 'contact':
        targetRef = contactRef;
        break;
      default:
        targetRef = null;
    }

    if (targetRef && targetRef.current) {
      const element = targetRef.current;

      if (element) {
        const relativeToCurrentView = () => {
          // relative to current view
          const elementPosition = element.getBoundingClientRect().top;
          const offsetPosition = elementPosition + window.scrollY - 100;

          window.scrollTo({
            top: offsetPosition,
            behavior: 'smooth'
          });
        }
        setTimeout(relativeToCurrentView, 50);
      }
    }
  };


  return (
    <Router>
      <div className="App">
        <Header scrollToSection={scrollToSection} />
        <Routes>
          <Route path="/" element={<Home ref={homeRef} />} />
          <Route path="/about" element={<About ref={aboutRef} />} />
          <Route path="/projects" element={<Projects ref={projectsRef} />} />
          <Route path="/contact" element={<Contact ref={contactRef} />} />
        </Routes>
        <Footer />
      </div>
    </Router>
  );
}

export default App;
```

