      import React, { useState, useEffect } from 'react';
      import { motion } from 'framer-motion';
      import './App.css';

      // Sample Testimonials (replace with actual data)
      const TESTIMONIALS = [
        {
          id: 1,
          name: "Alice Johnson",
          title: "CEO, InnovateTech",
          testimonial: "This app revolutionized our workflow. The interface is intuitive and the features are top-notch. Highly recommended!",
          image: "https://via.placeholder.com/150",
