          name: "Bob Williams",
          title: "CTO, FutureSolutions",
          testimonial: "The integration process was seamless. Their support team was responsive and helpful throughout the entire journey.",
          image: "https://via.placeholder.com/150",
        },
        {
          id: 3,
          name: "Charlie Davis",
          title: "Project Manager, GlobalCorp",
          testimonial: "We saw significant improvements in our team's productivity after implementing this solution. Great value for the investment.",
          image: "https://via.placeholder.com/150",
        },
      ];

      function App() {
        const [isDarkMode, setIsDarkMode] = useState(false);

        useEffect(() => {
          // Set initial theme based on user preference or local storage
          const storedMode = localStorage.getItem('theme');
          if (storedMode) {
            setIsDarkMode(storedMode === 'dark');
          }
        }, []);

        useEffect(() => {
          // Update the theme class on the body
          document.body.classList.toggle('dark-mode', isDarkMode);
          // Store the theme in local storage
